class Solution:
    def divisorGame(self, n: int) -> bool:
        dp = [False] * (n + 1)
        for k in range(2, n + 1):
            for x in range(1, k // 2 + 1):
                if k % x == 0 and not dp[k - x]:
                    dp[k] = True
                    break
        return dp[n]

c.cpp:
class Solution {
public:
    bool divisorGame(int n) {
        vector<bool> dp(n + 1, false);
        for (int k = 2; k <= n; ++k)
            for (int x = 1; x <= k / 2; ++x)
                if (k % x == 0 && !dp[k - x]) { dp[k] = true; break; }
        return dp[n];
    }
};

