var divisorGame = function(n) {
    const dp = new Array(n + 1).fill(false);
    for (let k = 2; k <= n; k++)
        for (let x = 1; x <= Math.floor(k / 2); x++)
            if (k % x === 0 && !dp[k - x]) { dp[k] = true; break; }
    return dp[n];
};

